package com.brightloop.payment;
import com.brightloop.catalog.Customer;import com.brightloop.invoice.Invoice;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;
@Entity @Table(name="payments") public class Payment{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id;@Column(name="payment_number",nullable=false,unique=true,length=40) String paymentNumber;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="invoice_id",nullable=false) Invoice invoice;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="customer_id",nullable=false) Customer customer;@Column(nullable=false,precision=14,scale=2) BigDecimal amount;@Column(name="payment_method",nullable=false,length=30) String paymentMethod;@Column(name="transaction_reference",length=120) String transactionReference;@Column(name="payment_date",nullable=false) Instant paymentDate=Instant.now();@Column(nullable=false,length=20) String status="COMPLETED";@Column(length=500) String notes;@Column(name="created_at",nullable=false,updatable=false) Instant createdAt=Instant.now();
 protected Payment(){}public Payment(String number,Invoice i,BigDecimal amount,String method,String reference,String notes){paymentNumber=number;invoice=i;customer=i.getCustomer();this.amount=amount;paymentMethod=method;transactionReference=reference;this.notes=notes;}public Long getId(){return id;}public String getPaymentNumber(){return paymentNumber;}public Invoice getInvoice(){return invoice;}public Customer getCustomer(){return customer;}public BigDecimal getAmount(){return amount;}public String getPaymentMethod(){return paymentMethod;}public String getTransactionReference(){return transactionReference;}public Instant getPaymentDate(){return paymentDate;}public String getStatus(){return status;}
}
